const opens = (event) => add_days(event.on, 1 - (event.kind === 'EXPECTED_MULTIPLE_BIRTH' ? row.multiple_pregnancy_days : row.days));
return ctx.entry.days.every((day) => births.some((event) => opens(event) <= day.date && day.date <= get(event, 'ended_on', day.date)));

// js
// 施行規則 art.24の4: a year's days taken in hours are capped, the year running from the grant day (労働基準法 art.39(4)).
const row = first(ctx.reads.leave_catalog).lookup;
const contract = first(ctx.reads.employee_contract);
const started = get(contract, 'service_started_on', contract.effective_range.from);
const yearOf = (date) => Math.floor((calendar_completed_months(started, date) - row.service_offset_months) / 12);
const held = ctx.reads.leave_catalog_entry;
const reversed = held.map((entry) => get(entry, 'reverses', null));
const standing = held.filter((entry) => entry.id !== get(ctx.entry, 'id', null) && get(entry, 'reverses', null) == null && !reversed.includes(entry.id));
const days = [...standing.flatMap((entry) => entry.days), ...ctx.entry.days];
return ctx.entry.days.every((day) => days.filter((other) => yearOf(other.date) === yearOf(day.date)).length / 2 <= row.annual_days_cap);

const terms = get(ctx.entry, 'terms', {});
const ext = get(ctx.entry, 'employee_extension_data', {});
const employmentType = get(ext, 'employment_type', null);
if (employmentType != null && !ctx.lookup.employment_types.includes(employmentType)) return false;
const classification = get(ext, 'work_classification', null);
if (classification != null && !ctx.lookup.work_classifications.includes(classification)) return false;
const category = get(terms, 'statutory_work_category', null);
if (category != null && !ctx.lookup.statutory_work_categories.includes(category)) return false;
const residency = get(terms, 'residency_status', null);
if (residency != null && !ctx.lookup.residency_statuses.includes(residency)) return false;
const method = get(terms, 'wage_payment_method', null);
if (method != null && !ctx.lookup.wage_payment_methods.includes(method)) return false;
return true;

const terms = get(ctx.entry, 'terms', {});
const day = get(terms, 'normal_hours_per_day', null);
if (day != null && (day < ctx.lookup.normal_hours_per_day_min || day > ctx.lookup.normal_hours_per_day_max)) return false;
const week = get(terms, 'normal_hours_per_week', null);
if (week != null && week < ctx.lookup.normal_hours_per_week_min) return false;
const days = get(terms, 'normal_days_per_week', null);
