return true;

const terms = get(ctx.entry, 'terms', {});
const ext = get(ctx.entry, 'employee_extension_data', {});
const region = get(terms, 'work_region', get(ext, 'work_region', null));
if (region != null && !ctx.lookup.work_regions.includes(region)) return false;
