const ext = get(ctx.entry, 'entity_extension_data', {});
const registration = get(ext, 'registration_number', null);
if (registration != null && String(registration).length !== ctx.lookup.registration_number_length) return false;
const month = get(ext, 'financial_year_end_month', null);
if (month != null && (Number(month) < 1 || Number(month) > 12 || Number(month) !== Math.trunc(Number(month)))) return false;
const week = get(ext, 'week_start', null);
if (week != null && (Number(week) < 0 || Number(week) > 6 || Number(week) !== Math.trunc(Number(week)))) return false;
const hours = get(ext, 'normal_hours_per_year', null);
if (hours != null && (Number(hours) <= 0 || Number(hours) > ctx.lookup.normal_hours_per_year_max)) return false;
const rest = get(ext, 'minimum_shift_rest_hours', null);
if (rest != null && (Number(rest) < 0 || Number(rest) > 24)) return false;
const age = get(ext, 'retirement_age_years', null);
if (age != null && (Number(age) < 0 || Number(age) !== Math.trunc(Number(age)))) return false;
return true;

return get(ctx.entry, 'registrations', []).every((r) => {
	if (!ctx.lookup.registration_schemes.includes(r.scheme_code)) return true;
	if (r.number == null || r.number === '') return true;
	return get(r, 'period', null) != null && r.period.from != null;
});

